INSERT INTO public.tracks (id, name, name_ar, tagline, tagline_ar, position) VALUES ('sonoff-installer-certification', 'SONOFF Installer Certification', 'اعتماد فني تركيب SONOFF', 'Master the SONOFF ecosystem: product portfolio, protocols, professional installation, and cross-platform smart home integration.', 'إتقان منظومة SONOFF: المنتجات والبروتوكولات والتركيب الاحترافي والدمج عبر منصات المنزل الذكي.', 5);
INSERT INTO public.modules (slug, code, track_id, title, title_ar, summary, summary_ar, external_url, position) VALUES ('sonoff-ecosystem-fundamentals', 'M11', 'sonoff-installer-certification', 'SONOFF Ecosystem Fundamentals', 'أساسيات منظومة SONOFF', 'SONOFF''s product portfolio, Wi-Fi/Zigbee 3.0/Matter protocols, the eWeLink platform, and product selection for real installation scenarios.', 'منتجات SONOFF وبروتوكولات Wi-Fi وZigbee 3.0 وMatter ومنصة eWeLink واختيار المنتج المناسب لسيناريوهات تركيب حقيقية.', NULL, 11);
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'The SONOFF Product Portfolio: An Installer''s Map', 'منتجات SONOFF: خريطة الفني', 'SONOFF''s catalog spans several device families that installers combine to build a complete smart home: DIY smart switches for retrofit wiring, smart wall switches for new or renovated circuits, plugs for appliance-level control, gateways and sensors for whole-home automation, home appliance controllers, and security cameras. Knowing which family solves which job — retrofit vs. new install, single load vs. multi-gang, wired vs. battery sensor — is the first skill every installer needs before touching a single device.', 'يضم كتالوج SONOFF عدة عائلات من الأجهزة يجمعها الفني لبناء منزل ذكي متكامل: مفاتيح DIY الذكية للتركيبات القائمة، مفاتيح الحائط الذكية للدوائر الجديدة أو المجددة، المقابس للتحكم بمستوى الجهاز، البوابات وأجهزة الاستشعار للأتمتة الشاملة، وحدات التحكم بالأجهزة المنزلية، وكاميرات المراقبة. معرفة العائلة المناسبة لكل مهمة — تركيب قائم مقابل تركيب جديد، حمل واحد مقابل عدة مفاتيح، جهاز سلكي مقابل حساس بطارية — هي أول مهارة يحتاجها أي فني قبل التعامل مع أي جهاز.', 1 FROM public.modules WHERE slug = 'sonoff-ecosystem-fundamentals';
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Communication Protocols: Wi-Fi, Zigbee 3.0 & Matter', 'بروتوكولات الاتصال: Wi-Fi وZigbee 3.0 وMatter', 'Modern SONOFF deployments mix three protocol families. Wi-Fi devices connect straight to the home router — simple to set up, but every device adds router load and depends on internet uptime for cloud features. Zigbee 3.0 devices form a local mesh network through a hub, giving lower power draw, faster local response, and resilience if internet drops. Matter is the newer cross-brand standard that lets compliant devices work natively across ecosystems like Apple Home, Google Home, and Amazon Alexa without vendor lock-in. A professional installer chooses the protocol per device role, not by default habit — heavy-traffic mesh nodes suit Zigbee, standalone single devices suit Wi-Fi, and multi-ecosystem households benefit from Matter.', 'تجمع تركيبات SONOFF الحديثة بين ثلاث عائلات بروتوكولات. أجهزة Wi-Fi تتصل مباشرة بموجه المنزل — إعداد بسيط، لكن كل جهاز يزيد حمل الموجه ويعتمد على استقرار الإنترنت لميزات السحابة. أجهزة Zigbee 3.0 تُكوّن شبكة شبكية محلية عبر بوابة، ما يمنح استهلاك طاقة أقل واستجابة محلية أسرع ومقاومة لانقطاع الإنترنت. أما Matter فهو المعيار الأحدث العابر للعلامات التجارية الذي يتيح للأجهزة المتوافقة العمل أصليًا عبر منظومات مثل Apple Home وGoogle Home وAmazon Alexa دون ارتباط بمورّد واحد. الفني المحترف يختار البروتوكول حسب دور الجهاز لا حسب العادة الافتراضية.', 2 FROM public.modules WHERE slug = 'sonoff-ecosystem-fundamentals';
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Working with the eWeLink Platform', 'العمل مع منصة eWeLink', 'eWeLink is SONOFF''s companion cloud/app platform for device provisioning, scene automation, and remote access. Installers use it to pair devices during commissioning, group devices into rooms and scenes, set up timers and conditional automations, and hand over a working account to the end customer. Understanding eWeLink''s device-sharing feature (so the installer can configure remotely without permanently owning the customer''s account) and its local-LAN mode (for reduced cloud dependency) are both essential professional skills.', 'eWeLink هي منصة SONOFF السحابية/التطبيقية المرافقة لتهيئة الأجهزة وأتمتة المشاهد والوصول عن بُعد. يستخدمها الفنيون لإقران الأجهزة أثناء التشغيل، وتجميعها في غرف ومشاهد، وضبط المؤقتات والأتمتة الشرطية، وتسليم حساب جاهز للعميل النهائي. فهم ميزة مشاركة الجهاز في eWeLink (لتمكين الفني من الإعداد عن بُعد دون امتلاك دائم لحساب العميل) ووضع الشبكة المحلية (لتقليل الاعتماد على السحابة) مهارتان أساسيتان للمحترفين.', 3 FROM public.modules WHERE slug = 'sonoff-ecosystem-fundamentals';
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Product Selection for Real-World Scenarios', 'اختيار المنتج المناسب لسيناريوهات واقعية', 'Choosing the right device starts with the load, the wiring, and the customer''s habits — not the spec sheet alone. A single-gang wall switch with no neutral wire needs a no-neutral-compatible switch model; a high-wattage appliance needs a plug or switch rated above its peak draw; a room requiring occupancy-based automation needs a motion or presence sensor paired to a hub, not a Wi-Fi-only device with no local trigger path. Matching device class to installation constraint before purchase avoids costly on-site swaps.', 'اختيار الجهاز المناسب يبدأ من الحمل والتمديدات وعادات العميل — لا من ورقة المواصفات وحدها. مفتاح حائط بلا سلك محايد يحتاج طرازًا متوافقًا مع عدم وجود محايد؛ جهاز عالي الاستهلاك يحتاج مقبسًا أو مفتاحًا بتصنيف أعلى من ذروة استهلاكه؛ غرفة تحتاج أتمتة قائمة على الإشغال تحتاج حساس حركة أو وجود مقترنًا ببوابة، لا جهاز Wi-Fi فقط بلا مسار تشغيل محلي. مطابقة فئة الجهاز مع قيود التركيب قبل الشراء يوفر استبدالات مكلفة في الموقع.', 4 FROM public.modules WHERE slug = 'sonoff-ecosystem-fundamentals';
INSERT INTO public.modules (slug, code, track_id, title, title_ar, summary, summary_ar, external_url, position) VALUES ('sonoff-professional-installation', 'M12', 'sonoff-installer-certification', 'Professional SONOFF Installation & Configuration', 'التركيب والإعداد الاحترافي لـ SONOFF', 'Installation best practices per product type, advanced configuration, automation design, project planning tools, and professional documentation/handover.', 'أفضل ممارسات التركيب حسب نوع المنتج، الإعداد المتقدم، تصميم الأتمتة، أدوات تخطيط المشروع، والتوثيق والتسليم الاحترافي.', NULL, 12);
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Installation Best Practices by Product Type', 'أفضل ممارسات التركيب حسب نوع المنتج', 'Each SONOFF product family has its own installation checklist. In-wall switches require verifying box depth, neutral availability, and load type (resistive, inductive, or LED-driver) before wiring. Plugs need a rating check against the appliance''s inrush current. Sensors need line-of-sight or mesh-repeater planning to avoid dead zones. Gateways should be placed centrally and away from thick concrete or metal obstructions. Following a per-product checklist — rather than treating every device the same — is what separates a professional install from a DIY one.', 'لكل عائلة منتجات SONOFF قائمة تحقق خاصة بالتركيب. مفاتيح الحائط تتطلب التحقق من عمق العلبة وتوفر السلك المحايد ونوع الحمل (مقاوم أو حثي أو دوائر LED) قبل التوصيل. المقابس تحتاج فحص التصنيف مقابل تيار الإقلاع للجهاز. أجهزة الاستشعار تحتاج تخطيطًا لخط الرؤية أو معيدات الشبكة لتفادي المناطق الميتة. البوابات يجب وضعها مركزيًا بعيدًا عن الخرسانة السميكة أو العوائق المعدنية. اتباع قائمة تحقق خاصة بكل منتج هو ما يميز التركيب الاحترافي عن الهاوٍ.', 1 FROM public.modules WHERE slug = 'sonoff-professional-installation';
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Advanced Device Configuration', 'الإعداد المتقدم للأجهزة', 'Beyond basic pairing, professional configuration covers: power-on state behavior (should the device restore its last state or a default after an outage?), inching/pulse mode for garage doors and gates, external switch detection for retrofit installs with existing wall switches, and firmware update scheduling. Configuring these settings correctly the first time avoids callback visits and builds customer trust.', 'بعد الإقران الأساسي، يشمل الإعداد الاحترافي: سلوك حالة التشغيل عند عودة الكهرباء (هل يستعيد الجهاز آخر حالة أم الحالة الافتراضية؟)، وضع النبضة للأبواب والبوابات الكهربائية، اكتشاف المفتاح الخارجي للتركيبات القائمة على مفاتيح حائط موجودة، وجدولة تحديثات البرامج الثابتة. ضبط هذه الإعدادات بشكل صحيح من أول مرة يوفر زيارات المتابعة ويبني ثقة العميل.', 2 FROM public.modules WHERE slug = 'sonoff-professional-installation';
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Automation Design Principles', 'مبادئ تصميم الأتمتة', 'Good automation starts from the customer''s daily routine, not from what the app can technically do. Map out triggers (time, sensor state, device state, geofence), conditions (only if..., except when...), and actions, then keep each automation single-purpose so it''s easy to debug. Avoid automation loops (device A triggers B which triggers A again) and always add a manual override path so the customer never feels locked out of their own switches.', 'الأتمتة الجيدة تبدأ من روتين العميل اليومي لا مما يستطيع التطبيق فعله تقنيًا. حدد المحفزات (الوقت، حالة الحساس، حالة الجهاز، السياج الجغرافي)، والشروط (فقط إذا...، إلا عندما...)، والإجراءات، ثم اجعل كل أتمتة ذات غرض واحد لتسهيل تشخيصها. تجنب حلقات الأتمتة (الجهاز أ يشغّل ب الذي يشغّل أ مجددًا) وأضف دائمًا مسار تحكم يدوي حتى لا يشعر العميل بأنه محروم من التحكم بمفاتيحه.', 3 FROM public.modules WHERE slug = 'sonoff-professional-installation';
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Using SONOFF Planning Tools', 'استخدام أدوات التخطيط في SONOFF', 'Before arriving on site, a professional installer sketches the device layout against the floor plan: switch positions, sensor coverage zones, gateway placement, and expected mesh hops. This planning pass catches problems — like a sensor placed too far from any repeater, or two gateways competing on the same Zigbee channel — before they become on-site rework.', 'قبل الوصول إلى الموقع، يرسم الفني المحترف مخطط توزيع الأجهزة على مخطط الأرضية: مواضع المفاتيح، مناطق تغطية الحساسات، موضع البوابة، وعدد قفزات الشبكة المتوقعة. هذا التخطيط المسبق يكشف المشكلات — مثل حساس بعيد جدًا عن أي معيد إشارة، أو بوابتين تتنافسان على نفس قناة Zigbee — قبل أن تتحول إلى إعادة عمل في الموقع.', 4 FROM public.modules WHERE slug = 'sonoff-professional-installation';
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Project Documentation & Handover', 'توثيق المشروع والتسليم', 'A complete project handover package includes: a device inventory with locations, network credentials stored securely, an automation summary in plain language for the customer, and a basic troubleshooting sheet (what to check if a device goes offline). Professional documentation reduces support calls and makes future expansions faster for any installer who revisits the site.', 'حزمة تسليم المشروع الكاملة تشمل: جردًا للأجهزة مع مواقعها، بيانات اعتماد الشبكة محفوظة بأمان، ملخص أتمتة بلغة مبسطة للعميل، وورقة استكشاف أعطال أساسية (ماذا تفعل إذا انقطع جهاز عن الشبكة). التوثيق الاحترافي يقلل مكالمات الدعم ويسرّع أي توسعات مستقبلية لأي فني يزور الموقع لاحقًا.', 5 FROM public.modules WHERE slug = 'sonoff-professional-installation';
INSERT INTO public.modules (slug, code, track_id, title, title_ar, summary, summary_ar, external_url, position) VALUES ('sonoff-smart-home-integration', 'M13', 'sonoff-installer-certification', 'SONOFF Smart Home Integration', 'دمج SONOFF في المنزل الذكي', 'Integrating SONOFF with Home Assistant and Homey, the Matter ecosystem, and cross-platform integration strategy for vendor-independent installations.', 'دمج SONOFF مع Home Assistant وHomey، منظومة Matter، واستراتيجية الدمج عبر المنصات لتركيبات مستقلة عن المورّد.', NULL, 13);
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Integrating SONOFF with Home Assistant', 'دمج SONOFF مع Home Assistant', 'Home Assistant is an open-source home automation platform that many advanced customers and installers prefer for full local control. SONOFF devices can be brought into Home Assistant through official integrations, local Zigbee coordinators, or Matter bridging. Installers working at this tier should understand entity naming conventions, how to expose SONOFF automations as Home Assistant helpers, and how to keep the eWeLink cloud and Home Assistant from fighting over the same device state.', 'Home Assistant منصة أتمتة منزلية مفتوحة المصدر يفضلها كثير من العملاء والفنيين المتقدمين للتحكم المحلي الكامل. يمكن دمج أجهزة SONOFF في Home Assistant عبر تكاملات رسمية، أو منسقات Zigbee محلية، أو ربط Matter. يجب على الفني في هذا المستوى فهم قواعد تسمية الكيانات، وكيفية إظهار أتمتة SONOFF كمساعدات في Home Assistant، وكيفية منع تضارب حالة الجهاز بين سحابة eWeLink وHome Assistant.', 1 FROM public.modules WHERE slug = 'sonoff-smart-home-integration';
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Integrating SONOFF with Homey', 'دمج SONOFF مع Homey', 'Homey is another popular hub platform offering a flow-based automation builder and wide protocol support. Bringing SONOFF devices into Homey typically uses community or official apps, and installers should verify device capability mapping (on/off, dimming, power metering) translates correctly so no functionality is lost compared to the native eWeLink app.', 'Homey منصة بوابة شائعة أخرى تقدم أداة بناء أتمتة قائمة على التدفقات ودعمًا واسعًا للبروتوكولات. إدخال أجهزة SONOFF إلى Homey يتم عادة عبر تطبيقات مجتمعية أو رسمية، ويجب على الفني التحقق من أن خرائط قدرات الجهاز (تشغيل/إيقاف، التعتيم، قياس الطاقة) تُترجم بشكل صحيح دون فقدان أي وظيفة مقارنة بتطبيق eWeLink الأصلي.', 2 FROM public.modules WHERE slug = 'sonoff-smart-home-integration';
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Deep Dive: The Matter Ecosystem', 'التعمق في منظومة Matter', 'Matter-certified SONOFF devices can join a Matter fabric controlled by any compliant hub — Apple Home, Google Home, Amazon Alexa, Home Assistant, or SmartThings — simultaneously in some configurations via multi-admin support. Installers at the gold tier should know how to commission a device onto a Matter fabric via QR/setup code, how multi-admin sharing works across ecosystems, and how to troubleshoot fabric commissioning failures (usually Thread border router or Wi-Fi band mismatches).', 'أجهزة SONOFF المعتمدة من Matter يمكنها الانضمام إلى نسيج Matter يتحكم به أي بوابة متوافقة — Apple Home وGoogle Home وAmazon Alexa وHome Assistant وSmartThings — في آن واحد في بعض الإعدادات عبر دعم تعدد المشرفين. يجب على الفني في المستوى الذهبي معرفة كيفية تشغيل جهاز على نسيج Matter عبر رمز QR/الإعداد، وكيفية عمل المشاركة متعددة المشرفين عبر المنظومات، وكيفية استكشاف أعطال تشغيل النسيج (غالبًا بسبب عدم تطابق موجه حدود Thread أو نطاق Wi-Fi).', 3 FROM public.modules WHERE slug = 'sonoff-smart-home-integration';
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Cross-Platform Integration Strategy', 'استراتيجية الدمج عبر المنصات', 'The highest-value skill for a certified installer is designing installations that don''t lock the customer into a single ecosystem. This means favoring Matter or open-API devices where possible, documenting fallback paths if a cloud service changes terms, and building automations at the protocol layer (Zigbee/Matter) rather than deep inside one app, so the installation survives ecosystem changes over the following years.', 'أعلى مهارة قيمة للفني المعتمد هي تصميم تركيبات لا تحبس العميل في منظومة واحدة. يعني هذا تفضيل أجهزة Matter أو ذات واجهة برمجية مفتوحة حيثما أمكن، وتوثيق مسارات بديلة في حال تغيرت شروط خدمة سحابية، وبناء الأتمتة على مستوى البروتوكول (Zigbee/Matter) بدلًا من داخل تطبيق واحد بعمق، حتى يستمر التركيب رغم تغيرات المنظومات خلال السنوات التالية.', 4 FROM public.modules WHERE slug = 'sonoff-smart-home-integration';
INSERT INTO public.quizzes (module_id, tier, title, title_ar, pass_percent) SELECT id, 'bronze', title || ' — Bronze Quiz', title_ar || ' — اختبار برونزي', 80 FROM public.modules WHERE slug = 'sonoff-ecosystem-fundamentals';
INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT q.id, 'A customer wants lower power draw and continued local response if the internet goes down. Which protocol family best fits?', 'يريد العميل استهلاك طاقة أقل واستجابة محلية مستمرة عند انقطاع الإنترنت. أي عائلة بروتوكولات الأنسب؟', 1 FROM public.quizzes q JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-ecosystem-fundamentals' AND q.tier = 'bronze';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'Zigbee 3.0 mesh through a hub', 'شبكة Zigbee 3.0 الشبكية عبر بوابة', TRUE, 1 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-ecosystem-fundamentals' AND q.tier = 'bronze' AND qq.question = 'A customer wants lower power draw and continued local response if the internet goes down. Which protocol family best fits?';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'Wi-Fi direct to the router only', 'Wi-Fi مباشرة إلى الموجه فقط', FALSE, 2 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-ecosystem-fundamentals' AND q.tier = 'bronze' AND qq.question = 'A customer wants lower power draw and continued local response if the internet goes down. Which protocol family best fits?';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'No protocol matters for this case', 'لا يهم البروتوكول في هذه الحالة', FALSE, 3 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-ecosystem-fundamentals' AND q.tier = 'bronze' AND qq.question = 'A customer wants lower power draw and continued local response if the internet goes down. Which protocol family best fits?';
INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT q.id, 'What must an installer verify before selecting a wall switch for a box with no neutral wire?', 'ماذا يجب أن يتحقق منه الفني قبل اختيار مفتاح حائط لعلبة بلا سلك محايد؟', 2 FROM public.quizzes q JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-ecosystem-fundamentals' AND q.tier = 'bronze';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'That the switch model supports no-neutral wiring', 'أن طراز المفتاح يدعم التوصيل بلا محايد', TRUE, 1 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-ecosystem-fundamentals' AND q.tier = 'bronze' AND qq.question = 'What must an installer verify before selecting a wall switch for a box with no neutral wire?';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'The color of the switch plate', 'لون غطاء المفتاح', FALSE, 2 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-ecosystem-fundamentals' AND q.tier = 'bronze' AND qq.question = 'What must an installer verify before selecting a wall switch for a box with no neutral wire?';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'The customer''s Wi-Fi password', 'كلمة مرور Wi-Fi للعميل', FALSE, 3 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-ecosystem-fundamentals' AND q.tier = 'bronze' AND qq.question = 'What must an installer verify before selecting a wall switch for a box with no neutral wire?';
