INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT q.id, 'Why should gateways be placed centrally and away from thick concrete or metal?', 'لماذا يجب وضع البوابات مركزيًا وبعيدًا عن الخرسانة السميكة أو المعدن؟', 1 FROM public.quizzes q JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-professional-installation' AND q.tier = 'bronze';
